function compactCard(id, title, shortTitle, group, category, memoryWord, coreIdea, symptoms, dsm, tip, extra = {}) {
  return {
    id,
    title,
    shortTitle,
    group,
    category,
    priority: extra.priority ?? "Βασικά",
    memoryWord,
    signals: extra.signals ?? { core: memoryWord, relation: "Κλινική εικόνα", risk: "Διαφορική διάγνωση" },
    coreIdea,
    thinkingFlow: extra.flow ?? [["Πυρήνας", coreIdea], ["Εικόνα", symptoms[0] ?? "Βασική κλινική εικόνα."], ["Διάκριση", dsm[0] ?? "Κράτα τη διαγνωστική θέση στην ύλη."], ["Εξέταση", tip]],
    axes: extra.axes ?? [[memoryWord, 88, "πυρήνας"], ["Τι βλέπω", 76, "κλινική εικόνα"], ["Τι ξεχωρίζω", 70, "διαφορική"], ["Τι κάνω", 56, "θεραπεία"]],
    symptoms,
    dsm,
    clinicalUnderstanding: extra.clinical ?? "Κράτα την κλινική λογική της ύλης: τι οργανώνει την εικόνα, τι πρέπει να ξεχωρίσεις και πώς συνδέεται με το ευρύτερο κεφάλαιο.",
    treatment: extra.treatment ?? ["Ψυχοεκπαίδευση και κλινική αξιολόγηση.", "Ψυχοθεραπευτική παρέμβαση ανάλογα με τη βαρύτητα και τη λειτουργικότητα.", "Φαρμακοθεραπεία όταν ενδείκνυται από την κλινική εικόνα.", "Πάντα έλεγχος διαφορικής διάγνωσης και κινδύνου."],
    cycle: extra.cycle ?? [memoryWord, "Σύμπτωμα", "Αποφυγή/έκπτωση", "Θεραπευτική στόχευση"],
    examTip: tip,
  };
}

