comparisonCards.forEach((card) => {
  const existing = disorders.findIndex((item) => item.id === card.id);
  if (existing >= 0) disorders[existing] = card;
  else disorders.push(card);
});
groups.forEach((group) => {
  const comparisons = comparisonCards.filter((card) => card.category === group.name);
  group.ids = [...comparisons.map((card) => card.id), ...group.ids.filter((id) => !comparisons.some((card) => card.id === id))];
});

