  categoryStat: document.querySelector("#categoryStat"),
  priorityStat: document.querySelector("#priorityStat"),
  cardGroup: document.querySelector("#cardGroup"),
  cardTitle: document.querySelector("#cardTitle"),
  coreIdea: document.querySelector("#coreIdea"),
